# 03. STUDY WINDOWS -----------------------------------------------------------
iso_monday <- function(yw) as.Date(ISOweek::ISOweek2date(paste0(yw, "-1")))
period_2_label <- "P2 - Epidemic 2023-2024"
period_bands <- tibble::tibble(
  label = c("P1 - Reference", "P2 - Study epidemic window", "P3 - Reference"),
  xmin = as.Date(c(iso_monday("2022-W30"), iso_monday("2023-W30"), iso_monday("2025-W18"))),
  xmax = as.Date(c(iso_monday("2023-W24"), iso_monday("2024-W24"), iso_monday("2025-W48"))) + 6
)
period_palette <- c("P1 - Reference" = "#DBEAFE",
                    "P2 - Study epidemic window" = "#FEE2E2",
                    "P3 - Reference" = "#DCFCE7")

# 04. AGE-STRATIFIED EMERGENCY VISITS AND ADMISSIONS ---------------------------
# Fictional probability allocations. These are NOT observed age distributions.
age_labels <- c("< 5", "5-14", "15-44", "45-64", "65+")
age_keys <- c("lt5", "5to14", "15to44", "45to64", "65plus")
ed_prob <- c(0.12, 0.10, 0.44, 0.24, 0.10)
hosp_prob <- c(0.07, 0.08, 0.31, 0.27, 0.27)
stopifnot(isTRUE(all.equal(sum(ed_prob), 1)),
          isTRUE(all.equal(sum(hosp_prob), 1)))

allocate_by_age <- function(counts, probs, column_prefix) {
  draws <- t(vapply(counts, function(value) {
    if (is.na(value) || value < 0 || value != as.integer(value)) {
      stop("Age allocation requires valid nonnegative integer counts.")
    }
    as.integer(rmultinom(n = 1, size = as.integer(value), prob = probs)[, 1])
  }, integer(length(probs))))
  colnames(draws) <- paste0(column_prefix, "_", age_keys)
  tibble::as_tibble(draws)
}

ed_age <- allocate_by_age(weekly$pasaj_deng, ed_prob, "ed")
hosp_age <- allocate_by_age(weekly$hospi_deng, hosp_prob, "hosp")
age_weekly <- dplyr::bind_cols(
  weekly %>% select(date, an_sem, period, pasaj_deng, hospi_deng),
  ed_age, hosp_age
)
stopifnot(
  all(rowSums(as.matrix(ed_age)) == weekly$pasaj_deng),
  all(rowSums(as.matrix(hosp_age)) == weekly$hospi_deng)
)

p2 <- age_weekly %>% filter(period == period_2_label)
stopifnot(nrow(p2) == 47L)

age_summary <- tibble::tibble(
  age_group = age_labels,
  emergency_visits = as.integer(colSums(p2[paste0("ed_", age_keys)])),
  hospital_admissions = as.integer(colSums(p2[paste0("hosp_", age_keys)]))
) %>%
  mutate(
    emergency_share_pct = round(100 * emergency_visits / sum(emergency_visits), 1),
    admission_share_pct = round(100 * hospital_admissions / sum(hospital_admissions), 1),
    combined_encounter_count = emergency_visits + hospital_admissions
  )

age_total <- age_summary %>%
  summarise(
    age_group = "TOTAL",
    emergency_visits = sum(emergency_visits),
    hospital_admissions = sum(hospital_admissions),
    emergency_share_pct = 100,
    admission_share_pct = 100,
    combined_encounter_count = sum(combined_encounter_count)
  )
age_table <- bind_rows(age_summary, age_total)

age_validation <- tibble::tibble(
  check = c("P2 weeks", "Age-stratified ED visits", "P2 total ED visits",
            "Age-stratified hospital admissions", "P2 total hospital admissions",
            "ED reconciliation difference", "Admission reconciliation difference"),
  value = c(nrow(p2), sum(age_summary$emergency_visits), sum(p2$pasaj_deng),
            sum(age_summary$hospital_admissions), sum(p2$hospi_deng),
            sum(age_summary$emergency_visits) - sum(p2$pasaj_deng),
            sum(age_summary$hospital_admissions) - sum(p2$hospi_deng))
)
stopifnot(age_validation$value[6] == 0, age_validation$value[7] == 0)

# Age chart and table, side-by-side, like the original reporting workflow.
age_long <- age_summary %>%
  select(age_group, emergency_visits, hospital_admissions) %>%
  pivot_longer(-age_group, names_to = "care_type", values_to = "count") %>%
  mutate(
    care_type = recode(care_type,
      emergency_visits = "Emergency visits",
      hospital_admissions = "Hospital admissions"),
    age_group = factor(age_group, levels = age_labels)
  )

p_age_chart <- ggplot(age_long, aes(age_group, count, fill = care_type)) +
  geom_col(position = position_dodge(width = 0.78), width = 0.7) +
