# 05. COMPARATIVE DENGUE / RESPIRATORY DISEASE DYNAMICS ------------------------
# Unlike the previous full-window module, this supplement focuses on
# 2022-2025, with one panel for each dengue indicator, preserving the
# distinction between sentinel CCE and biologically confirmed/probable cases.
weekly_view <- weekly %>%
  filter(date >= as.Date("2022-01-01"), date <= as.Date("2025-12-31"))

normalize_minmax <- function(x) {
  keep <- is.finite(x)
  if (!any(keep)) return(rep(NA_real_, length(x)))
  lo <- min(x[keep]); hi <- max(x[keep])
  if (lo == hi) return(ifelse(keep, 0, NA_real_))
  (x - lo) / (hi - lo)
}

variables <- c("rms_estim", "dengue_cas_bio", "grippe_cce", "covid_cce", "bronchio_cce")
dynamics <- weekly_view %>%
  select(date, all_of(variables)) %>%
  pivot_longer(-date, names_to = "indicator", values_to = "count") %>%
  group_by(indicator) %>%
  arrange(date, .by_group = TRUE) %>%
  mutate(
    smoothed_3weeks = zoo::rollmean(count, k = 3, fill = NA_real_, align = "center"),
    normalized = normalize_minmax(smoothed_3weeks)
  ) %>%
  ungroup()

series_colors <- c("Dengue" = "#E63946", "Influenza" = "#457B9D",
                   "COVID-19" = "#6A994E", "Bronchiolitis" = "#9B72CF")

make_comparison <- function(dengue_indicator, panel_title) {
  d <- dynamics %>%
    filter(indicator %in% c(dengue_indicator, "grippe_cce", "covid_cce", "bronchio_cce")) %>%
    mutate(disease = case_when(
      indicator == dengue_indicator ~ "Dengue",
      indicator == "grippe_cce" ~ "Influenza",
      indicator == "covid_cce" ~ "COVID-19",
      indicator == "bronchio_cce" ~ "Bronchiolitis",
      TRUE ~ "Other"
    ),
    disease = factor(disease, levels = names(series_colors)))
  ggplot(d, aes(date, normalized, color = disease, group = disease)) +
    geom_rect(data = period_bands,
              aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf, fill = label),
              inherit.aes = FALSE, alpha = 0.22) +
    geom_line(linewidth = 0.65, na.rm = TRUE) +
    scale_fill_manual(values = period_palette, guide = "none") +
    scale_color_manual(values = series_colors, name = NULL) +
    scale_x_date(date_breaks = "4 months", date_labels = "%b %Y") +
    scale_y_continuous(limits = c(0, 1.05), breaks = seq(0, 1, 0.25),
                       labels = scales::label_percent()) +
    labs(title = panel_title,
         x = NULL, y = "Within-series relative intensity") +
    theme_minimal(base_size = 10) +
    theme(plot.title = element_text(face = "bold"),
          legend.position = "bottom", panel.grid.minor = element_blank(),
          axis.text.x = element_text(angle = 30, hjust = 1))
}

p_cces <- make_comparison("rms_estim", "A - Dengue sentinel estimated consultations (CCE)")
p_bio <- make_comparison("dengue_cas_bio", "B - Dengue confirmed + probable cases")
p_disease_comparison <- p_cces / p_bio +
  plot_annotation(
    title = "Synthetic comparative disease dynamics - 2022 to 2025",
    subtitle = "Centered 3-week averages; independent min-max normalization for each series",
    caption = paste(
      "Synthetic observations only. Study-period shading is illustrative.",
      "Normalized series compare timing and shapes, not case burden."
    )
  )
ggsave(file.path(figures_dir, "epidemiology_comparative_dynamics_synthetic.png"),
       p_disease_comparison, width = 16, height = 10, dpi = 300, bg = "white")

# A separate, shared-axis two-panel figure follows the updated reporting layout:
