resp <- dynamics %>%
  filter(indicator %in% c("grippe_cce", "covid_cce", "bronchio_cce")) %>%
  mutate(disease = recode(indicator,
    grippe_cce = "Influenza", covid_cce = "COVID-19", bronchio_cce = "Bronchiolitis"))

deng <- dynamics %>% filter(indicator == "rms_estim")
p_deng_top <- ggplot(deng, aes(date, normalized)) +
  geom_rect(data = period_bands,
            aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf, fill = label),
            inherit.aes = FALSE, alpha = 0.22) +
  geom_line(color = series_colors[["Dengue"]], linewidth = 0.85, na.rm = TRUE) +
  scale_fill_manual(values = period_palette, guide = "none") +
  scale_x_date(date_breaks = "4 months", date_labels = "%b %Y") +
  scale_y_continuous(limits = c(0, 1.05), breaks = c(0, .5, 1),
                     labels = scales::label_percent()) +
  labs(y = "Dengue\nrelative intensity", x = NULL) +
  theme_minimal(base_size = 10) +
  theme(axis.text.x = element_blank(), panel.grid.minor = element_blank())

p_resp_bottom <- ggplot(resp, aes(date, normalized, color = disease)) +
  geom_rect(data = period_bands,
            aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf, fill = label),
            inherit.aes = FALSE, alpha = 0.22) +
  geom_line(linewidth = 0.7, na.rm = TRUE) +
  scale_fill_manual(values = period_palette, guide = "none") +
  scale_color_manual(values = series_colors[c("Influenza", "COVID-19", "Bronchiolitis")], name = NULL) +
  scale_x_date(date_breaks = "4 months", date_labels = "%b %Y") +
  scale_y_continuous(limits = c(0, 1.05), breaks = c(0, .5, 1),
                     labels = scales::label_percent()) +
  labs(y = "Respiratory diseases\nrelative intensity", x = "Epidemiological week") +
  theme_minimal(base_size = 10) +
  theme(legend.position = "bottom", panel.grid.minor = element_blank(),
        axis.text.x = element_text(angle = 30, hjust = 1))

p_separated <- p_deng_top / p_resp_bottom +
  plot_layout(heights = c(1, 1.1)) +
  plot_annotation(
    title = "Synthetic dengue and respiratory disease dynamics",
    subtitle = "Independent 0-1 normalization - demonstration of comparative surveillance reporting",
    caption = "Fictional disease curves and reference windows. No actual outbreak timing can be inferred."
  )
ggsave(file.path(figures_dir, "epidemiology_dengue_respiratory_panels_synthetic.png"),
       p_separated, width = 14, height = 9, dpi = 300, bg = "white")

# 06. ILLUSTRATIVE COST COMPONENT DECOMPOSITION -------------------------------
# Completely fictional standalone graphic. These amounts were newly invented;
# they do not reproduce the component figures in the original research script,
# and they DO NOT reconcile to the separate Monte Carlo simulation module.
# This visual is a demonstration of economic reporting, not a cost estimate.
costs <- tibble::tibble(
  component = c("Ambulatory care", "Hospital stays", "Productivity losses",
                "Laboratory testing", "Emergency care", "Pharmaceuticals"),
  classification = c("Direct", "Direct", "Indirect", "Direct", "Direct", "Direct"),
  # Arbitrary, entirely fictional input values, in euros
  illustrative_eur = c(2620000, 1190000, 740000, 410000, 83000, 19000)
) %>%
  mutate(
    pct = 100 * illustrative_eur / sum(illustrative_eur),
    component = reorder(component, illustrative_eur),
    value_label = paste0(sprintf("%.2f M EUR", illustrative_eur / 1e6),
                         " (", sprintf("%.1f%%", pct), ")")
  )

p_costs <- ggplot(costs, aes(illustrative_eur / 1e6, component, fill = classification)) +
  geom_col(width = 0.7) +
  geom_text(aes(label = value_label), hjust = -0.08, size = 3.2) +
  scale_fill_manual(values = c("Direct" = "#2E86AB", "Indirect" = "#D97706")) +
  scale_x_continuous(expand = expansion(mult = c(0, 0.3))) +
  labs(title = "Fictional cost-of-illness component breakdown",
       subtitle = paste0("Illustrative standalone scenario: ",
                         sprintf("%.2f million EUR", sum(costs$illustrative_eur) / 1e6)),
       x = "Illustrative monetary amount (million EUR)", y = NULL, fill = NULL,
       caption = paste(
         "Entirely fictional component values. Not observed Martinique costs.",
         "Independent from the repository's Monte Carlo estimates."
       )) +
  theme_minimal(base_size = 11) +
  theme(plot.title = element_text(face = "bold"), legend.position = "top",
        panel.grid.major.y = element_blank(), panel.grid.minor = element_blank())

ggsave(file.path(figures_dir, "epidemiology_cost_components_synthetic.png"),
       p_costs, width = 12, height = 6, dpi = 300, bg = "white")

# 07. EXPORT REPRODUCIBLE TABLES ----------------------------------------------
outputs <- list(
  "epidemiology_age_care_synthetic.csv" = age_table,
  "epidemiology_age_care_validation_synthetic.csv" = age_validation,
  "epidemiology_cost_components_synthetic.csv" = costs %>%
    transmute(component = as.character(component), classification,
              illustrative_eur, share_pct = round(pct, 1))
)
for (filename in names(outputs)) {
  readr::write_csv(outputs[[filename]], file.path(tables_dir, filename))
}

figures <- c(
  "epidemiology_age_care_synthetic.png",
  "epidemiology_comparative_dynamics_synthetic.png",
  "epidemiology_dengue_respiratory_panels_synthetic.png",
